from itertools import product
def paridade_par(palavra):
    estado=0
    for simbolo in palavra: estado ^= int(simbolo)
    return estado==0
casos=0
for n in range(5):
    for bits in product('01',repeat=n):
        palavra=''.join(bits)
        assert paridade_par(palavra)==(palavra.count('1')%2==0)
        casos+=1
assert casos==31
